175→export async function loadActivePoliciesForIdentity(
176→  surreal: Surreal,
177→  identityId: string,
178→  workspaceId: string,
179→): Promise<PolicyRecord[]> {
180→  const identityRecord = new RecordId("identity", identityId);
181→  const workspaceRecord = new RecordId("workspace", workspaceId);
182→
183→  // Identity-linked policies
184→  const identityPolicies = (await surreal.query(
185→    `SELECT ->governing->policy.* AS policies FROM $identity;`,
186→    { identity: identityRecord },
187→  )) as Array<Array<{ policies: PolicyRecord[] }>>;
188→
189→  // Workspace-linked policies
190→  const workspacePolicies = (await surreal.query(
191→    `SELECT <-protects<-policy.* AS policies FROM $workspace;`,
192→    { workspace: workspaceRecord },
193→  )) as Array<Array<{ policies: PolicyRecord[] }>>;
194→
195→  const idPolicies = identityPolicies[0]?.[0]?.policies ?? [];
196→  const wsPolicies = workspacePolicies[0]?.[0]?.policies ?? [];
197→
198→  // Deduplicate by policy ID and filter active only
199→  const seen = new Set<string>();
200→  const all: PolicyRecord[] = [];
201→  for (const p of [...idPolicies, ...wsPolicies]) {
202→    const id = p.id.id as string;
203→    if (!seen.has(id) && p.status === "active") {
204→      seen.add(id);
205→      all.push(p);
206→    }
207→  }
208→  return all;
209→}
