211→export async function simulatePolicyGateResult(
212→  surreal: Surreal,
213→  intentId: string,
214→  result: {
215→    decision: "APPROVE" | "REJECT";
216→    risk_score: number;
217→    reason: string;
218→    policy_only: boolean;
219→    policy_trace: PolicyTraceEntry[];
220→    human_veto_required?: boolean;
221→    evidence_requirement?: {
222→      min_count: number;
223→      required_types: string[];
224→    };
225→  },
226→  resultStatus: "authorized" | "pending_veto" | "vetoed",
227→): Promise<void> {
228→  const intentRecord = new RecordId("intent", intentId);
229→  const evalContent: Record<string, unknown> = {
230→    decision: result.decision,
231→    risk_score: result.risk_score,
232→    reason: result.reason,
233→    evaluated_at: new Date(),
234→    policy_only: result.policy_only,
235→    policy_trace: result.policy_trace,
236→  };
237→  if (result.human_veto_required !== undefined) {
238→    evalContent.human_veto_required = result.human_veto_required;
239→  }
240→  if (result.evidence_requirement !== undefined) {
241→    evalContent.evidence_requirement = result.evidence_requirement;
242→  }
243→
244→  const updates: Record<string, unknown> = {
245→    status: resultStatus,
246→    evaluation: evalContent,
247→    updated_at: new Date(),
248→  };
249→
250→  if (resultStatus === "pending_veto") {
251→    updates.veto_expires_at = new Date(Date.now() + 5 * 60 * 1000);
252→  }
253→
254→  await surreal.query(`UPDATE $intent MERGE $updates;`, {
255→    intent: intentRecord,
256→    updates,
257→  });
258→}
