420→/** Build version chain formatted as PolicyVersionChainItem[]. */
421→export async function buildVersionChain(
422→  surreal: Surreal,
423→  policy: PolicyRecord,
424→): Promise<PolicyVersionChainItem[]> {
425→  const chain = await resolveChainFromPool(surreal, policy);
426→  return chain.map((v) => ({
427→    id: v.id.id as string,
428→    version: v.version,
429→    status: v.status,
430→    created_at: formatTimestamp(v.created_at),
431→  }));
432→}
