 20→// Pure identity guard
 21→// ---------------------------------------------------------------------------
 22→
 23→/** Agents are denied mutation access to policies. */
 24→const isAgentIdentity = (identityType: string): boolean =>
 25→  identityType === "agent";
 26→
 27→// ---------------------------------------------------------------------------
 28→// Identity resolution (session -> person -> identity)
 29→// ---------------------------------------------------------------------------
 30→
 31→type IdentityInfo = {
 32→  identityRecord: RecordId<"identity", string>;
 33→  identityType: string;
 34→};
 35→
 36→async function resolveIdentityFromSession(
 37→  deps: ServerDependencies,
 38→  request: Request,
 39→): Promise<IdentityInfo | Response> {
 40→  const session = await deps.auth.api.getSession({ headers: request.headers });
 41→  if (!session?.user?.id) {
 42→    return jsonError("authentication required", 401);
 43→  }
 44→
 45→  const personRecord = new RecordId("person", session.user.id);
 46→
 47→  const [identityRows] = await deps.surreal.query<[RecordId<"identity", string>[]]>(
 48→    "SELECT VALUE in FROM identity_person WHERE out = $person LIMIT 1;",
 49→    { person: personRecord },
 50→  );
 51→  const identityRecord = identityRows[0] as RecordId<"identity", string> | undefined;
 52→  if (!identityRecord) {
 53→    return jsonError("identity not found for user", 500);
 54→  }
 55→
 56→  const [typeRows] = await deps.surreal.query<[Array<{ type: string }>]>(
 57→    "SELECT type FROM $identity;",
 58→    { identity: identityRecord },
 59→  );
 60→  const identityType = typeRows[0]?.type;
 61→  if (!identityType) {
 62→    return jsonError("identity type not found", 500);
 63→  }
 64→
 65→  return { identityRecord, identityType };
 66→}
