 76→async function resolveWorkspace(
 77→  deps: ServerDependencies,
 78→  workspaceId: string,
 79→  logEvent: string,
 80→): Promise<RecordId<"workspace", string> | Response> {
 81→  try {
 82→    return await resolveWorkspaceRecord(deps.surreal, workspaceId);
 83→  } catch (error) {
 84→    if (error instanceof HttpError) {
 85→      return jsonError(error.message, error.status);
 86→    }
 87→    log.error(logEvent, "Failed to resolve workspace", error, { workspaceId });
 88→    return jsonError("failed to resolve workspace", 500);
 89→  }
 90→}
