372→// POST /api/workspaces/:workspaceId/policies/:policyId/versions (stub - guarded)
373→// ---------------------------------------------------------------------------
374→
375→/** Only active policies can spawn new versions. */
376→const VERSIONABLE_STATUSES: ReadonlySet<PolicyStatus> = new Set<PolicyStatus>(["active"]);
377→
378→async function handleCreatePolicyVersion(
379→  deps: ServerDependencies,
380→  workspaceId: string,
381→  policyId: string,
382→  request: Request,
383→): Promise<Response> {
384→  const guardResult = await requireHumanIdentity(deps, request);
385→  if (isResponse(guardResult)) return guardResult;
386→
387→  const workspaceOrError = await resolveWorkspace(deps, workspaceId, "policy.version.workspace_resolve.failed");
388→  if (isResponse(workspaceOrError)) return workspaceOrError;
389→  const workspaceRecord = workspaceOrError;
390→
391→  try {
392→    const sourcePolicy = await getPolicyById(deps.surreal, policyId, workspaceRecord);
393→    if (!sourcePolicy) {
394→      return jsonError("policy not found", 404);
395→    }
396→
397→    if (!VERSIONABLE_STATUSES.has(sourcePolicy.status)) {
398→      return jsonError(
399→        `policy must be in active status to create a new version (current: ${sourcePolicy.status})`,
400→        409,
401→      );
402→    }
403→
404→    // Parse optional overrides from request body — callers can customise the
405→    // new draft instead of getting an exact copy of the source policy.
406→    let overrides: Partial<{
407→      title: string;
408→      description: string;
409→      selector: PolicySelector;
410→      rego_source: string;
411→      human_veto_required: boolean;
412→      max_ttl: string;
413→    }> = {};
414→    try {
415→      const raw = await request.json();
416→      if (raw && typeof raw === "object") overrides = raw as typeof overrides;
417→    } catch {
418→      // No body or invalid JSON — use source values only.
419→    }
420→
421→    // When overrides include rego_source, validate through the same path as create.
422→    if (overrides.rego_source !== undefined) {
423→      const validation = await validatePolicyCreateBody({
424→        title: overrides.title ?? sourcePolicy.title,
425→        description: overrides.description ?? sourcePolicy.description ?? "",
426→        rego_source: overrides.rego_source,
427→      });
428→      if (!validation.valid) {
429→        if (validation.compileErrors && validation.compileErrors.length > 0) {
430→          return jsonResponse({ error: validation.errors[0], errors: validation.compileErrors }, 400);
431→        }
432→        return jsonError(validation.errors[0], 400);
433→      }
434→    }
435→
436→    const sourcePolicyRecord = new RecordId("policy", policyId);
437→    const { policyId: newPolicyId, version } = await createPolicy(deps.surreal, {
438→      title: overrides.title ?? sourcePolicy.title,
439→      description: overrides.description ?? sourcePolicy.description,
440→      selector: overrides.selector ?? sourcePolicy.selector,
441→      rego_source: overrides.rego_source ?? sourcePolicy.rego_source,
442→      human_veto_required: overrides.human_veto_required ?? sourcePolicy.human_veto_required,
443→      max_ttl: overrides.max_ttl ?? sourcePolicy.max_ttl,
444→      createdBy: guardResult.identityRecord,
445→      workspace: workspaceRecord,
446→      supersedes: sourcePolicyRecord,
447→    });
448→
449→    return jsonResponse({ policy_id: newPolicyId, version }, 201);
450→  } catch (error) {
451→    log.error("policy.version.failed", "Failed to create policy version", error, { workspaceId, policyId });
452→    return jsonError("failed to create policy version", 500);
453→  }
454→}
