  1→/**
  2→ * Policy CRUD UI Acceptance Test Kit
  3→ *
  4→ * Extends policy-test-kit with HTTP API helpers for testing the
  5→ * Policy CRUD endpoints. Tests invoke through the driving ports
  6→ * (HTTP API endpoints) exclusively.
  7→ *
  8→ * Driving ports:
  9→ *   GET    /api/workspaces/:wsId/policies
 10→ *   GET    /api/workspaces/:wsId/policies/:id
 11→ *   GET    /api/workspaces/:wsId/policies/:id/versions
 12→ *   POST   /api/workspaces/:wsId/policies
 13→ *   PATCH  /api/workspaces/:wsId/policies/:id/activate
 14→ *   PATCH  /api/workspaces/:wsId/policies/:id/deprecate
 15→ *   POST   /api/workspaces/:wsId/policies/:id/versions
 16→ */
 17→import { RecordId, type Surreal } from "surrealdb";
 18→
 19→// Re-export everything from policy-test-kit
 20→export {
 21→  setupOrchestratorSuite,
 22→  createTestUser,
 23→  createTestWorkspace,
 24→  createTestIdentity,
 25→  createPolicy,
