  1→/**
  2→ * Milestone 3: Policy Lifecycle (Activate + Deprecate)
  3→ *
  4→ * Traces: US-PCUI-04 (Activate/Deprecate Policy)
  5→ *
  6→ * Validates the status transitions of the policy lifecycle:
  7→ * draft -> active (creates governing/protects edges),
  8→ * active -> deprecated (removes edges), and rejection of
  9→ * invalid transitions.
 10→ *
 11→ * Driving ports:
 12→ *   PATCH /api/workspaces/:wsId/policies/:id/activate
 13→ *   PATCH /api/workspaces/:wsId/policies/:id/deprecate
 14→ *   GET   /api/workspaces/:wsId/policies/:id
 15→ */
 16→import { describe, expect, it } from "bun:test";
 17→import { RecordId } from "surrealdb";
 18→import {
 19→  setupAcceptanceSuite,
 20→  createTestUser,
 21→  createTestWorkspace,
 22→  createTestIdentity,
 23→  createPolicy,
 24→  activatePolicy,
 25→  deprecatePolicy,
 26→  loadActivePoliciesForIdentity,
 27→  createPolicyViaApi,
 28→  activatePolicyViaApi,
 29→  deprecatePolicyViaApi,
 30→  getPolicyDetail,
 31→  buildPolicyBody,
 32→  buildMinimalRule,
 33→  type PolicyDetailResponse,
 34→} from "./policy-crud-test-kit";
 35→
 36→const getRuntime = setupAcceptanceSuite("policy_crud_m3_lifecycle");
 37→
 38→// =============================================================================
 39→// US-PCUI-04: Activate Policy
 40→// =============================================================================
 41→
 42→describe("Milestone 3: Policy Activation (US-PCUI-04)", () => {
 43→
 44→  // ---------------------------------------------------------------------------
 45→  // Walking Skeleton: Admin activates a draft policy
 46→  // AC: Draft -> active, governing and protects edges created
 47→  // ---------------------------------------------------------------------------
 48→  it("admin activates a draft policy and governance edges are created", async () => {
 49→    const { baseUrl, surreal } = getRuntime();
 50→
 51→    // Given a draft policy with one deny rule
 52→    const user = await createTestUser(baseUrl, "m3-activate-happy");
 53→    const workspace = await createTestWorkspace(baseUrl, user);
 54→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
 55→
 56→    const createResponse = await createPolicyViaApi(
 57→      baseUrl,
 58→      user.headers,
 59→      workspace.workspaceId,
 60→      buildPolicyBody({
 61→        title: "Deploy Guard",
 62→        rules: [buildMinimalRule({
 63→          id: "block_deploy",
 64→          condition: { field: "action_spec.action", operator: "eq", value: "deploy" },
 65→          effect: "deny",
 66→          priority: 100,
 67→        })],
 68→      }),
 69→    );
 70→    const { policy_id: policyId } = await createResponse.json() as { policy_id: string };
 71→
 72→    // When admin activates the policy
 73→    const response = await activatePolicyViaApi(
 74→      baseUrl, user.headers, workspace.workspaceId, policyId,
 75→    );
 76→
 77→    // Then the policy status transitions to active
 78→    expect(response.status).toBe(200);
 79→    const body = await response.json() as { status: string };
 80→    expect(body.status).toBe("active");
 81→
 82→    // And the policy detail confirms active status
 83→    const detailResponse = await getPolicyDetail(
 84→      baseUrl, user.headers, workspace.workspaceId, policyId,
 85→    );
 86→    const detail = await detailResponse.json() as PolicyDetailResponse;
 87→    expect(detail.policy.status).toBe("active");
 88→
 89→    // And governing and protects edges are created
 90→    expect(detail.edges.governing.length).toBeGreaterThanOrEqual(1);
 91→    expect(detail.edges.protects.length).toBeGreaterThanOrEqual(1);
 92→  }, 120_000);
 93→
 94→  // ---------------------------------------------------------------------------
 95→  // Cannot activate an already-active policy
 96→  // AC: PATCH /activate on active policy returns 409
 97→  // ---------------------------------------------------------------------------
 98→  it("cannot activate an already-active policy", async () => {
 99→    const { baseUrl, surreal } = getRuntime();
100→
101→    // Given an active policy
102→    const user = await createTestUser(baseUrl, "m3-activate-again");
103→    const workspace = await createTestWorkspace(baseUrl, user);
104→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
105→
106→    const { policyId } = await createPolicy(surreal, workspace.workspaceId, adminId, {
107→      title: "Already Active",
108→      rules: [{ id: "r1", condition: { field: "action_spec.action", operator: "eq", value: "deploy" }, effect: "deny", priority: 100 }],
109→    });
110→    await activatePolicy(surreal, policyId, adminId, workspace.workspaceId);
111→
112→    // When admin attempts to activate it again
113→    const response = await activatePolicyViaApi(
114→      baseUrl, user.headers, workspace.workspaceId, policyId,
115→    );
116→
117→    // Then the request is rejected
118→    expect(response.status).toBe(409);
119→    const body = await response.json() as { error: string };
120→    expect(body.error).toContain("draft");
121→  }, 120_000);
122→
123→  // ---------------------------------------------------------------------------
124→  // Cannot activate a deprecated policy
125→  // AC: PATCH /activate on deprecated policy returns 409
126→  // ---------------------------------------------------------------------------
127→  it("cannot activate a deprecated policy", async () => {
128→    const { baseUrl, surreal } = getRuntime();
129→
130→    // Given a deprecated policy
131→    const user = await createTestUser(baseUrl, "m3-activate-deprecated");
132→    const workspace = await createTestWorkspace(baseUrl, user);
133→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
134→
135→    const { policyId } = await createPolicy(surreal, workspace.workspaceId, adminId, {
136→      title: "Deprecated Policy",
137→      rules: [{ id: "r1", condition: { field: "action_spec.action", operator: "eq", value: "deploy" }, effect: "deny", priority: 100 }],
138→    });
139→    await activatePolicy(surreal, policyId, adminId, workspace.workspaceId);
140→    await deprecatePolicy(surreal, policyId);
141→
142→    // When admin attempts to activate the deprecated policy
143→    const response = await activatePolicyViaApi(
144→      baseUrl, user.headers, workspace.workspaceId, policyId,
145→    );
146→
147→    // Then the request is rejected
148→    expect(response.status).toBe(409);
149→  }, 120_000);
150→
151→  // ---------------------------------------------------------------------------
152→  // Cannot activate a superseded policy
153→  // AC: PATCH /activate on superseded policy returns 409
154→  // ---------------------------------------------------------------------------
155→  it("cannot activate a superseded policy", async () => {
156→    const { baseUrl, surreal } = getRuntime();
157→
158→    // Given a superseded policy (v1 superseded by v2)
159→    const user = await createTestUser(baseUrl, "m3-activate-superseded");
160→    const workspace = await createTestWorkspace(baseUrl, user);
161→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
162→
163→    const { policyId: v1Id } = await createPolicy(surreal, workspace.workspaceId, adminId, {
164→      title: "Original Policy",
165→      rules: [{ id: "r1", condition: { field: "action_spec.action", operator: "eq", value: "deploy" }, effect: "deny", priority: 100 }],
166→    });
167→    await activatePolicy(surreal, v1Id, adminId, workspace.workspaceId);
168→
169→    // Supersede v1 by creating and activating v2
170→    // (simulate via direct DB update to put v1 in superseded state)
171→    const v1Record = new RecordId("policy", v1Id);
172→    await surreal.query(
173→      `UPDATE $policy SET status = 'superseded', updated_at = time::now();`,
174→      { policy: v1Record },
175→    );
176→
177→    // When admin attempts to activate the superseded v1
178→    const response = await activatePolicyViaApi(
179→      baseUrl, user.headers, workspace.workspaceId, v1Id,
180→    );
181→
182→    // Then the request is rejected
183→    expect(response.status).toBe(409);
184→  }, 120_000);
185→});
186→
187→// =============================================================================
188→// US-PCUI-04: Deprecate Policy
189→// =============================================================================
190→
191→describe("Milestone 3: Policy Deprecation (US-PCUI-04)", () => {
192→
193→  // ---------------------------------------------------------------------------
194→  // Admin deprecates an active policy and edges are removed
195→  // AC: Active -> deprecated, governing and protects edges removed
196→  // ---------------------------------------------------------------------------
197→  it("admin deprecates an active policy and governance edges are removed", async () => {
198→    const { baseUrl, surreal } = getRuntime();
199→
200→    // Given an active policy with governing and protects edges
201→    const user = await createTestUser(baseUrl, "m3-deprecate-happy");
202→    const workspace = await createTestWorkspace(baseUrl, user);
203→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
204→
205→    const { policyId } = await createPolicy(surreal, workspace.workspaceId, adminId, {
206→      title: "Policy to Deprecate",
207→      rules: [{ id: "r1", condition: { field: "action_spec.action", operator: "eq", value: "deploy" }, effect: "deny", priority: 100 }],
208→    });
209→    await activatePolicy(surreal, policyId, adminId, workspace.workspaceId);
210→
211→    // Verify edges exist before deprecation
212→    const policiesBefore = await loadActivePoliciesForIdentity(surreal, adminId, workspace.workspaceId);
213→    expect(policiesBefore.map(p => p.id.id as string)).toContain(policyId);
214→
215→    // When admin deprecates the policy
216→    const response = await deprecatePolicyViaApi(
217→      baseUrl, user.headers, workspace.workspaceId, policyId,
218→    );
219→
220→    // Then the policy is deprecated
221→    expect(response.status).toBe(200);
222→    const body = await response.json() as { status: string };
223→    expect(body.status).toBe("deprecated");
224→
225→    // And the detail confirms deprecated status with no edges
226→    const detailResponse = await getPolicyDetail(
227→      baseUrl, user.headers, workspace.workspaceId, policyId,
228→    );
229→    const detail = await detailResponse.json() as PolicyDetailResponse;
230→    expect(detail.policy.status).toBe("deprecated");
231→    expect(detail.edges.governing).toHaveLength(0);
232→    expect(detail.edges.protects).toHaveLength(0);
233→
234→    // And the policy is excluded from active policy loading
235→    const policiesAfter = await loadActivePoliciesForIdentity(surreal, adminId, workspace.workspaceId);
236→    expect(policiesAfter.map(p => p.id.id as string)).not.toContain(policyId);
237→  }, 120_000);
238→
239→  // ---------------------------------------------------------------------------
240→  // Cannot deprecate a draft policy
241→  // AC: PATCH /deprecate on draft policy returns 409
242→  // ---------------------------------------------------------------------------
243→  it("cannot deprecate a draft policy", async () => {
244→    const { baseUrl, surreal } = getRuntime();
245→
