  1→/**
  2→ * Milestone 6: Policy Trace Integration
  3→ *
  4→ * Traces: US-PCUI-06 (Policy Trace in Review)
  5→ *
  6→ * Validates that when an intent is evaluated against active policies,
  7→ * the policy_trace on the intent record captures which policies and
  8→ * rules matched, enabling reviewers to see the governance reasoning.
  9→ *
 10→ * Driving ports:
 11→ *   POST  /api/workspaces/:wsId/policies (create)
 12→ *   PATCH /api/workspaces/:wsId/policies/:id/activate
 13→ *   GET   /api/workspaces/:wsId/policies/:id (policy detail for trace links)
 14→ *   Direct DB for intent creation + policy gate simulation
 15→ */
 16→import { describe, expect, it } from "bun:test";
 17→import {
 18→  setupAcceptanceSuite,
 19→  createTestUser,
 20→  createTestWorkspace,
 21→  createTestIdentity,
 22→  createPolicy,
 23→  activatePolicy,
 24→  createDraftIntent,
 25→  submitIntent,
 26→  simulatePolicyGateResult,
 27→  getIntentRecord,
 28→  getPolicyDetail,
 29→  type PolicyTraceEntry,
 30→  type PolicyDetailResponse,
 31→} from "./policy-crud-test-kit";
 32→
 33→const getRuntime = setupAcceptanceSuite("policy_crud_m6_trace");
 34→
 35→// =============================================================================
 36→// US-PCUI-06: Policy Trace in Review
 37→// =============================================================================
 38→
 39→describe("Milestone 6: Policy Trace on Intent Evaluation (US-PCUI-06)", () => {
 40→
 41→  // ---------------------------------------------------------------------------
 42→  // Walking Skeleton: Intent evaluation persists policy trace
 43→  // AC: Reviewer can see which rules matched and why on the intent record
 44→  // ---------------------------------------------------------------------------
 45→  it("intent evaluation includes policy trace with matching rules", async () => {
 46→    const { baseUrl, surreal } = getRuntime();
 47→
 48→    // Given an active policy with a deny rule
 49→    const user = await createTestUser(baseUrl, "m6-trace-happy");
 50→    const workspace = await createTestWorkspace(baseUrl, user);
 51→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
 52→    const agentId = await createTestIdentity(surreal, "coding-agent", "agent", workspace.workspaceId);
 53→
 54→    const { policyId } = await createPolicy(surreal, workspace.workspaceId, adminId, {
 55→      title: "Deploy Blocker",
 56→      rules: [{
 57→        id: "block_prod_deploy",
 58→        condition: { field: "action_spec.action", operator: "eq", value: "deploy" },
 59→        effect: "deny",
 60→        priority: 100,
 61→      }],
 62→    });
 63→    await activatePolicy(surreal, policyId, adminId, workspace.workspaceId);
 64→
 65→    // And an intent that triggers the deny rule
 66→    const { intentId } = await createDraftIntent(surreal, workspace.workspaceId, agentId, {
 67→      goal: "Deploy feature branch to production",
 68→      reasoning: "Feature is complete and tested",
 69→      action_spec: { provider: "infra", action: "deploy", params: {} },
 70→    });
 71→    await submitIntent(surreal, intentId);
 72→
 73→    // When the policy gate evaluates the intent
 74→    const trace: PolicyTraceEntry[] = [{
 75→      policy_id: policyId,
 76→      policy_version: 1,
 77→      rule_id: "block_prod_deploy",
 78→      effect: "deny",
 79→      matched: true,
 80→      priority: 100,
 81→    }];
 82→
 83→    await simulatePolicyGateResult(surreal, intentId, {
 84→      decision: "REJECT",
 85→      risk_score: 0,
 86→      reason: "Policy deny rule 'block_prod_deploy' matched",
 87→      policy_only: true,
 88→      policy_trace: trace,
 89→    }, "vetoed");
 90→
 91→    // Then the intent record contains the policy trace
 92→    const record = await getIntentRecord(surreal, intentId);
 93→    const evaluation = record.evaluation as Record<string, unknown>;
 94→    const persistedTrace = evaluation.policy_trace as PolicyTraceEntry[];
 95→
 96→    expect(persistedTrace).toHaveLength(1);
 97→    expect(persistedTrace[0].policy_id).toBe(policyId);
 98→    expect(persistedTrace[0].policy_version).toBe(1);
 99→    expect(persistedTrace[0].rule_id).toBe("block_prod_deploy");
100→    expect(persistedTrace[0].effect).toBe("deny");
101→    expect(persistedTrace[0].matched).toBe(true);
102→    expect(persistedTrace[0].priority).toBe(100);
103→  }, 120_000);
104→
105→  // ---------------------------------------------------------------------------
106→  // Policy trace captures both matched and unmatched rules
107→  // AC: Trace shows full picture of rule evaluation
108→  // ---------------------------------------------------------------------------
109→  it("policy trace captures both matched and unmatched rules", async () => {
110→    const { baseUrl, surreal } = getRuntime();
111→
112→    // Given two active policies with rules that partially match
113→    const user = await createTestUser(baseUrl, "m6-trace-mixed");
114→    const workspace = await createTestWorkspace(baseUrl, user);
115→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
116→    const agentId = await createTestIdentity(surreal, "coding-agent", "agent", workspace.workspaceId);
117→
118→    const { policyId: p1 } = await createPolicy(surreal, workspace.workspaceId, adminId, {
119→      title: "Deploy Guard",
120→      rules: [{
121→        id: "block_deploy",
122→        condition: { field: "action_spec.action", operator: "eq", value: "deploy" },
123→        effect: "deny",
124→        priority: 100,
125→      }],
126→    });
127→    await activatePolicy(surreal, p1, adminId, workspace.workspaceId);
128→
129→    const { policyId: p2 } = await createPolicy(surreal, workspace.workspaceId, adminId, {
130→      title: "Read Allowance",
131→      rules: [{
132→        id: "allow_read",
133→        condition: { field: "action_spec.action", operator: "eq", value: "read" },
134→        effect: "allow",
135→        priority: 10,
136→      }],
137→    });
138→    await activatePolicy(surreal, p2, adminId, workspace.workspaceId);
139→
140→    // And a read intent (matches allow_read, not block_deploy)
141→    const { intentId } = await createDraftIntent(surreal, workspace.workspaceId, agentId, {
142→      goal: "Read project configuration",
143→      reasoning: "Need config for implementation",
144→      action_spec: { provider: "file_reader", action: "read", params: {} },
145→    });
146→    await submitIntent(surreal, intentId);
147→
148→    // When the policy gate evaluates the intent
149→    const trace: PolicyTraceEntry[] = [
150→      { policy_id: p1, policy_version: 1, rule_id: "block_deploy", effect: "deny", matched: false, priority: 100 },
151→      { policy_id: p2, policy_version: 1, rule_id: "allow_read", effect: "allow", matched: true, priority: 10 },
152→    ];
153→
154→    await simulatePolicyGateResult(surreal, intentId, {
155→      decision: "APPROVE",
156→      risk_score: 5,
157→      reason: "No deny rules matched, allow rule matched",
158→      policy_only: false,
159→      policy_trace: trace,
160→    }, "authorized");
161→
162→    // Then both rule evaluations are captured in the trace
163→    const record = await getIntentRecord(surreal, intentId);
164→    const evaluation = record.evaluation as Record<string, unknown>;
165→    const persistedTrace = evaluation.policy_trace as PolicyTraceEntry[];
166→
167→    expect(persistedTrace).toHaveLength(2);
168→
169→    // And the deny rule is marked as not matched
170→    const denyEntry = persistedTrace.find(t => t.rule_id === "block_deploy");
171→    expect(denyEntry?.matched).toBe(false);
172→    expect(denyEntry?.effect).toBe("deny");
173→
174→    // And the allow rule is marked as matched
175→    const allowEntry = persistedTrace.find(t => t.rule_id === "allow_read");
176→    expect(allowEntry?.matched).toBe(true);
177→    expect(allowEntry?.effect).toBe("allow");
178→  }, 120_000);
179→
180→  // ---------------------------------------------------------------------------
181→  // Policy trace links back to policy detail
182→  // AC: Each trace entry's policy_id resolves to a valid policy detail
183→  // ---------------------------------------------------------------------------
184→  it("policy trace entries link to retrievable policy details", async () => {
185→    const { baseUrl, surreal } = getRuntime();
186→
187→    // Given an evaluated intent with a policy trace
188→    const user = await createTestUser(baseUrl, "m6-trace-link");
189→    const workspace = await createTestWorkspace(baseUrl, user);
190→    const adminId = await createTestIdentity(surreal, "admin", "human", workspace.workspaceId);
191→    const agentId = await createTestIdentity(surreal, "coding-agent", "agent", workspace.workspaceId);
192→
193→    const { policyId } = await createPolicy(surreal, workspace.workspaceId, adminId, {
194→      title: "Linkable Policy",
195→      rules: [{
196→        id: "check_budget",
197→        condition: { field: "budget_limit.amount", operator: "gt", value: 500 },
198→        effect: "deny",
199→        priority: 50,
200→      }],
201→    });
202→    await activatePolicy(surreal, policyId, adminId, workspace.workspaceId);
203→
204→    const { intentId } = await createDraftIntent(surreal, workspace.workspaceId, agentId, {
205→      goal: "Purchase expensive tool license",
206→      reasoning: "Team needs new tooling",
207→      action_spec: { provider: "billing", action: "purchase", params: {} },
208→      budget_limit: { amount: 999, currency: "USD" },
209→    });
210→    await submitIntent(surreal, intentId);
211→
212→    await simulatePolicyGateResult(surreal, intentId, {
213→      decision: "REJECT",
214→      risk_score: 0,
215→      reason: "Budget exceeds policy limit",
216→      policy_only: true,
217→      policy_trace: [{
218→        policy_id: policyId,
219→        policy_version: 1,
220→        rule_id: "check_budget",
221→        effect: "deny",
222→        matched: true,
223→        priority: 50,
224→      }],
225→    }, "vetoed");
226→
227→    // When a reviewer follows the policy_id from the trace to the policy detail
228→    const record = await getIntentRecord(surreal, intentId);
229→    const evaluation = record.evaluation as Record<string, unknown>;
230→    const persistedTrace = evaluation.policy_trace as PolicyTraceEntry[];
231→    const tracePolicyId = persistedTrace[0].policy_id;
232→
233→    const detailResponse = await getPolicyDetail(
234→      baseUrl, user.headers, workspace.workspaceId, tracePolicyId,
235→    );
236→
237→    // Then the policy detail is retrievable
238→    expect(detailResponse.status).toBe(200);
239→    const detail = await detailResponse.json() as PolicyDetailResponse;
240→    expect(detail.policy.title).toBe("Linkable Policy");
241→    expect(detail.policy.rules[0].id).toBe("check_budget");
242→  }, 120_000);
243→
244→  // ---------------------------------------------------------------------------
245→  // Empty policy trace when no policies are active
246→  // AC: Intent evaluated with no active policies has empty trace
247→  // ---------------------------------------------------------------------------
248→  it("intent evaluated with no active policies has empty policy trace", async () => {
249→    const { baseUrl, surreal } = getRuntime();
250→
251→    // Given a workspace with no active policies
252→    const user = await createTestUser(baseUrl, "m6-trace-empty");
253→    const workspace = await createTestWorkspace(baseUrl, user);
254→    const agentId = await createTestIdentity(surreal, "coding-agent", "agent", workspace.workspaceId);
255→
256→    // And an intent submitted in this workspace
257→    const { intentId } = await createDraftIntent(surreal, workspace.workspaceId, agentId, {
258→      goal: "Refactor utils module",
259→      reasoning: "Code cleanup",
260→      action_spec: { provider: "file_editor", action: "edit_file", params: {} },
261→    });
262→    await submitIntent(surreal, intentId);
263→
264→    // When the policy gate evaluates with no policies
265→    await simulatePolicyGateResult(surreal, intentId, {
266→      decision: "APPROVE",
267→      risk_score: 10,
268→      reason: "No policies configured",
269→      policy_only: false,
270→      policy_trace: [],
271→    }, "authorized");
272→
273→    // Then the policy trace is empty
274→    const record = await getIntentRecord(surreal, intentId);
275→    const evaluation = record.evaluation as Record<string, unknown>;
276→    const persistedTrace = evaluation.policy_trace as PolicyTraceEntry[];
277→    expect(persistedTrace).toHaveLength(0);
278→  }, 120_000);
279→});
