  1→/**
  2→ * Pure validation functions for policy creation request bodies.
  3→ *
  4→ * Validates Rego source compilation via Regorus.
  5→ * All domain errors are values — no exceptions thrown.
  6→ */
  7→
  8→import { compileRego, POLICY_PACKAGE_NAME, type CompileError } from "./rego-evaluator";
  9→
 10→// ---------------------------------------------------------------------------
 11→// Result type
 12→// ---------------------------------------------------------------------------
 13→
 14→export type ValidationResult =
 15→  | { valid: true }
 16→  | { valid: false; errors: string[]; compileErrors?: CompileError[] };
 17→
 18→// ---------------------------------------------------------------------------
 19→// Required package declaration
 20→// ---------------------------------------------------------------------------
 21→
 22→const REQUIRED_PACKAGE = POLICY_PACKAGE_NAME;
 23→
 24→// ---------------------------------------------------------------------------
 25→// Top-level body validation
 26→// ---------------------------------------------------------------------------
 27→
 28→type PolicyCreateInput = {
 29→  title: unknown;
 30→  description: unknown;
 31→  rego_source: unknown;
 32→  [key: string]: unknown;
 33→};
 34→
 35→const validateTitle = (title: unknown): string | undefined => {
 36→  if (typeof title !== "string" || title.trim() === "") {
 37→    return "title is required and must be a non-empty string";
 38→  }
 39→  return undefined;
 40→};
 41→
 42→const validateDescription = (description: unknown): string | undefined => {
 43→  if (typeof description !== "string" || description.trim() === "") {
 44→    return "description is required and must be a non-empty string";
 45→  }
 46→  return undefined;
 47→};
 48→
 49→const validateRegoSourcePresent = (regoSource: unknown): string | undefined => {
 50→  if (typeof regoSource !== "string" || regoSource.trim() === "") {
 51→    return "rego_source is required and must be a non-empty string";
 52→  }
 53→  return undefined;
 54→};
 55→
 56→const hasRequiredPackage = (regoSource: string): boolean => {
 57→  // Check that the Rego source declares "package osabio.policy"
 58→  // Package declaration appears as: `package osabio.policy`
 59→  // with possible leading whitespace and optional trailing content on the line
 60→  const escapedPackage = REQUIRED_PACKAGE.replace(/\./g, "\\.");
 61→  const packagePattern = new RegExp(`^\\s*package\\s+${escapedPackage}\\s*$`, "m");
 62→  return packagePattern.test(regoSource);
 63→};
 64→
 65→// ---------------------------------------------------------------------------
 66→// Intent context validation (for test endpoint)
 67→// ---------------------------------------------------------------------------
 68→
 69→/**
 70→ * Validates the IntentEvaluationContext shape submitted to the policy test endpoint.
 71→ *
 72→ * Only action_spec is required — it must be a non-null object containing
 73→ * action (string) and provider (string). All other fields are optional.
 74→ */
 75→export const validateIntentContext = (
 76→  body: unknown,
 77→): ValidationResult => {
 78→  if (body === null || body === undefined || typeof body !== "object") {
 79→    return { valid: false, errors: ["request body must be an object"] };
 80→  }
 81→
 82→  const parsed = body as Record<string, unknown>;
 83→  const errors: string[] = [];
 84→
 85→  const actionSpec = parsed.action_spec;
 86→  if (actionSpec === null || actionSpec === undefined || typeof actionSpec !== "object") {
 87→    errors.push("action_spec is required and must be an object");
 88→    return { valid: false, errors };
 89→  }
 90→
 91→  const spec = actionSpec as Record<string, unknown>;
 92→
 93→  if (typeof spec.action !== "string" || spec.action.trim() === "") {
 94→    errors.push("action_spec.action is required and must be a non-empty string");
 95→  }
 96→
 97→  if (typeof spec.provider !== "string" || spec.provider.trim() === "") {
 98→    errors.push("action_spec.provider is required and must be a non-empty string");
 99→  }
100→
101→  if (errors.length > 0) {
102→    return { valid: false, errors };
103→  }
104→
105→  return { valid: true };
106→};
107→
108→export async function validatePolicyCreateBody(
109→  body: PolicyCreateInput,
110→): Promise<ValidationResult> {
111→  if (body === null || body === undefined) {
112→    return { valid: false, errors: ["request body is required"] };
113→  }
114→
115→  const errors: string[] = [];
116→
117→  // Validate title
118→  const titleError = validateTitle(body.title);
119→  if (titleError) errors.push(titleError);
120→
121→  // Validate description
122→  const descriptionError = validateDescription(body.description);
123→  if (descriptionError) errors.push(descriptionError);
124→
125→  // Reject legacy rules field — clean break from predicate-based validation
126→  if ("rules" in body && body.rules !== undefined) {
127→    errors.push("rules field is not supported, use rego_source instead");
128→    return { valid: false, errors };
129→  }
130→
131→  // Validate rego_source presence
132→  const regoSourceError = validateRegoSourcePresent(body.rego_source);
133→  if (regoSourceError) {
134→    errors.push(regoSourceError);
135→    return { valid: false, errors };
136→  }
137→
138→  // At this point rego_source is a non-empty string
139→  const regoSource = body.rego_source as string;
140→
141→  // Validate package declaration before attempting compilation
142→  if (!hasRequiredPackage(regoSource)) {
143→    errors.push(`policy must declare package ${REQUIRED_PACKAGE}`);
144→    return { valid: false, errors };
145→  }
146→
147→  // Return any earlier errors (title/description) without attempting compilation
148→  if (errors.length > 0) {
149→    return { valid: false, errors };
150→  }
151→
152→  // Compile Rego source via Regorus WASM
153→  const compileResult = await compileRego(regoSource);
154→  if (!compileResult.success) {
155→    return {
156→      valid: false,
157→      errors: ["Invalid Rego syntax"],
158→      compileErrors: compileResult.errors,
159→    };
160→  }
161→
162→  return { valid: true };
163→}
164→

302→export async function createPolicyVersion(
303→  surreal: Surreal,
304→  oldPolicyId: string,
305→  workspaceId: string,
306→  createdById: string,
307→  newRegoSource: string,
308→): Promise<{ policyId: string }> {
309→  const oldPolicy = await getPolicyRecord(surreal, oldPolicyId);
310→  const newPolicyId = `policy-${crypto.randomUUID()}`;
311→  const newPolicyRecord = new RecordId("policy", newPolicyId);
312→  const oldPolicyRecord = new RecordId("policy", oldPolicyId);
313→  const workspaceRecord = new RecordId("workspace", workspaceId);
314→  const createdByRecord = new RecordId("identity", createdById);
315→
316→  await surreal.query(`
317→    BEGIN TRANSACTION;
318→      CREATE $newPolicy CONTENT {
319→        title: $title,
320→        version: $newVersion,
321→        status: 'active',
322→        selector: $selector,
323→        rego_source: $regoSource,
324→        human_veto_required: $vetoRequired,
325→        created_by: $createdBy,
326→        workspace: $workspace,
327→        supersedes: $oldPolicy,
328→        created_at: time::now()
329→      };
330→      UPDATE $oldPolicy SET status = 'superseded', updated_at = time::now();
331→    COMMIT TRANSACTION;
332→  `, {
333→    newPolicy: newPolicyRecord,
334→    oldPolicy: oldPolicyRecord,
335→    title: oldPolicy.title,
336→    newVersion: (oldPolicy.version as number) + 1,
337→    selector: oldPolicy.selector,
338→    regoSource: newRegoSource,
339→    vetoRequired: oldPolicy.human_veto_required,
340→    createdBy: createdByRecord,
341→    workspace: workspaceRecord,
342→  });
343→
344→  return { policyId: newPolicyId };
345→}
346→

