377→  const workspaceRecord = new RecordId("workspace", workspaceId);
378→  const rows = (await surreal.query(
379→    `SELECT count() AS total FROM task WHERE workspace = $ws AND status = "completed" GROUP ALL;`,
380→    { ws: workspaceRecord },
381→  )) as Array<Array<{ total: number }>>;
382→  return rows[0]?.[0]?.total ?? 0;
