429→  agents: Array<{ name: string; type?: "human" | "agent" }>,
430→): Promise<Array<{ name: string; identityId: string; identityRecord: RecordId<"identity"> }>> {
431→  const results: Array<{ name: string; identityId: string; identityRecord: RecordId<"identity"> }> = [];
432→  for (const agent of agents) {
