 90→export async function createPolicy(
 91→  surreal: Surreal,
 92→  workspaceId: string,
 93→  createdById: string,
 94→  opts: CreatePolicyOptions,
 95→): Promise<{ policyId: string; policyRecord: RecordId<"policy"> }> {
 96→  const policyId = `policy-${crypto.randomUUID()}`;
 97→  const policyRecord = new RecordId("policy", policyId);
 98→  const workspaceRecord = new RecordId("workspace", workspaceId);
 99→  const createdByRecord = new RecordId("identity", createdById);
100→
101→  const content: Record<string, unknown> = {
102→    title: opts.title,
103→    version: 1,
104→    status: opts.status ?? "draft",
105→    selector: opts.selector ?? {},
106→    rego_source: opts.rego_source,
107→    human_veto_required: opts.human_veto_required ?? false,
108→    created_by: createdByRecord,
109→    workspace: workspaceRecord,
110→    created_at: new Date(),
111→  };
112→
113→  if (opts.description) content.description = opts.description;
114→  if (opts.max_ttl) content.max_ttl = opts.max_ttl;
115→
116→  await surreal.query(`CREATE $policy CONTENT $content;`, {
117→    policy: policyRecord,
118→    content,
119→  });
120→
121→  return { policyId, policyRecord };
122→}
