124→export async function activatePolicy(
125→  surreal: Surreal,
126→  policyId: string,
127→  creatorId: string,
128→  workspaceId: string,
129→): Promise<void> {
130→  const policyRecord = new RecordId("policy", policyId);
131→  const creatorRecord = new RecordId("identity", creatorId);
132→  const workspaceRecord = new RecordId("workspace", workspaceId);
133→
134→  await surreal.query(`
135→    BEGIN TRANSACTION;
136→      UPDATE $policy SET status = 'active', updated_at = time::now();
137→      RELATE $creator->governing->$policy SET created_at = time::now();
138→      RELATE $policy->protects->$workspace SET created_at = time::now();
139→    COMMIT TRANSACTION;
140→  `, {
141→    policy: policyRecord,
142→    creator: creatorRecord,
143→    workspace: workspaceRecord,
144→  });
145→}
