275→/**
276→ * Creates multiple scored behavior records with staggered timestamps for trend testing.
277→ */
278→export async function createScoredBehaviorTrend(
279→  surreal: Surreal,
280→  workspaceId: string,
281→  identityId: string,
282→  metricType: string,
283→  definitionId: string,
284→  scores: number[],
285→): Promise<{ behaviorIds: string[] }> {
286→  const behaviorIds: string[] = [];
287→  const now = Date.now();
288→
289→  for (let i = 0; i < scores.length; i++) {
290→    const created_at = new Date(now - (scores.length - 1 - i) * 24 * 60 * 60 * 1000);
291→    const { behaviorId } = await createScoredBehaviorRecord(surreal, workspaceId, identityId, {
292→      metric_type: metricType,
293→      score: scores[i],
294→      definitionId,
295→      source_telemetry: { session_index: i },
296→      created_at,
297→    });
298→    behaviorIds.push(behaviorId);
299→  }
300→
301→  return { behaviorIds };
302→}
