297→/**
298→ * Creates multiple consecutive behavior records for trend testing.
299→ * Records are created with staggered timestamps to simulate sessions over time.
300→ */
301→export async function createBehaviorTrend(
302→  surreal: Surreal,
303→  workspaceId: string,
304→  identityId: string,
305→  metricType: string,
306→  scores: number[],
307→): Promise<{ behaviorIds: string[]; definitionId: string }> {
308→  const behaviorIds: string[] = [];
309→  const now = Date.now();
310→
311→  // Create one shared definition for the whole trend
312→  const { definitionId } = await createBehaviorDefinition(surreal, workspaceId, {
313→    title: metricType,
314→  });
315→
316→  for (let i = 0; i < scores.length; i++) {
317→    // Each record 1 day apart, oldest first
318→    const created_at = new Date(now - (scores.length - 1 - i) * 24 * 60 * 60 * 1000);
319→    const { behaviorId } = await createBehaviorRecord(surreal, workspaceId, identityId, {
320→      metric_type: metricType,
321→      score: scores[i],
322→      source_telemetry: { session_index: i },
323→      created_at,
324→      definitionId,
325→    });
326→    behaviorIds.push(behaviorId);
327→  }
328→
329→  return { behaviorIds, definitionId };
330→}
