498→/**
499→ * Creates a deterministic 1536-dim test embedding vector.
500→ *
501→ * Vectors with the same primaryDim share high cosine similarity.
502→ * Vectors with different primaryDims are near-orthogonal.
503→ */
504→export function makeTestEmbedding(primaryDim: number, secondaryDim?: number): number[] {
505→  const vec = new Array(1536).fill(0);
506→  vec[primaryDim % 1536] = 1.0;
507→  if (secondaryDim !== undefined) vec[secondaryDim % 1536] = 0.3;
508→  const mag = Math.sqrt(vec.reduce((s, v) => s + v * v, 0));
509→  return vec.map((v) => v / mag);
510→}
