512→/**
513→ * Runs the alignment adapter to find objectives matching an intent embedding.
514→ * Direct call to the SurrealDB KNN adapter — no authorizer pipeline.
515→ */
516→export async function findAlignedObjectives(
517→  surreal: Surreal,
518→  intentEmbedding: number[],
519→  workspaceId: string,
520→): Promise<Array<{ objectiveId: string; title: string; score: number }>> {
521→  const workspaceRecord = new RecordId("workspace", workspaceId);
522→  const rows = (await surreal.query(
523→    `LET $candidates = SELECT id, title, workspace, status,
524→        vector::similarity::cosine(embedding, $vec) AS score
525→      FROM objective WHERE embedding <|20, COSINE|> $vec;
526→     SELECT id, title, score FROM $candidates
527→      WHERE workspace = $ws AND status = 'active'
528→      ORDER BY score DESC LIMIT 10;`,
529→    { vec: intentEmbedding, ws: workspaceRecord },
530→  )) as [null, Array<{ id: RecordId<"objective">; title: string; score: number }>];
531→
532→  const candidates = rows[1] ?? [];
533→  return candidates.map((row) => ({
534→    objectiveId: row.id.id as string,
535→    title: row.title,
536→    score: row.score,
537→  }));
538→}
