  1→import type { RecordId, Surreal } from "surrealdb";
  2→import type {
  3→  PolicyRecord,
  4→  PolicyGateResult,
  5→  PolicyTraceEntry,
  6→  PolicyGateWarning,
  7→  PolicyEvidenceRequirements,
  8→  IntentEvaluationContext,
  9→} from "./types";
 10→import {
 11→  evaluateRegoPolicy,
 12→  createEngineCache,
 13→  type RegoEvaluationResult,
 14→} from "./rego-evaluator";
 15→import { loadActivePolicies } from "./policy-queries";
 16→
 17→// ---------------------------------------------------------------------------
 18→// Pipeline Types
 19→// ---------------------------------------------------------------------------
 20→
 21→type EvaluatedPolicy = {
 22→  policyId: string;
 23→  policyVersion: number;
 24→  humanVetoRequired: boolean;
 25→  denied: boolean;
 26→  denyMessages: string[];
 27→  evidenceRequirement: RegoEvaluationResult["evidence_requirement"];
 28→  warnings: PolicyGateWarning[];
 29→};
 30→
 31→// ---------------------------------------------------------------------------
 32→// Pure Pipeline Functions
 33→// ---------------------------------------------------------------------------
 34→
 35→export const deduplicatePolicies = (
 36→  policies: PolicyRecord[],
 37→): PolicyRecord[] => {
 38→  const seen = new Set<string>();
 39→  const result: PolicyRecord[] = [];
 40→
 41→  for (const policy of policies) {
 42→    const id = policy.id.id as string;
 43→    if (!seen.has(id)) {
 44→      seen.add(id);
 45→      result.push(policy);
 46→    }
 47→  }
 48→
 49→  return result;
 50→};
 51→
 52→export const buildGateResult = (
 53→  evaluatedPolicies: EvaluatedPolicy[],
 54→  denyMatched: boolean,
 55→  warnings: PolicyGateWarning[],
 56→  evidenceRequirements?: PolicyEvidenceRequirements,
 57→): PolicyGateResult => {
 58→  const policyTrace: PolicyTraceEntry[] = evaluatedPolicies.map((entry) => ({
 59→    policy_id: entry.policyId,
 60→    policy_version: entry.policyVersion,
 61→    // For Rego policies: rule_id contains the policy ID (one entry per policy)
 62→    rule_id: entry.policyId,
 63→    effect: entry.denied ? "deny" : "allow",
 64→    matched: entry.denied,
 65→    priority: 0,
 66→  }));
 67→
 68→  if (denyMatched) {
 69→    const denyEntry = evaluatedPolicies.find((entry) => entry.denied);
 70→    return {
 71→      passed: false,
 72→      reason: `Rego policy '${denyEntry!.policyId}' denied: ${denyEntry!.denyMessages.join("; ")}`,
 73→      policy_trace: policyTrace,
 74→      deny_rule_id: denyEntry!.policyId,
 75→      warnings,
 76→    };
 77→  }
 78→
 79→  const humanVetoRequired = evaluatedPolicies.some(
 80→    (entry) => entry.humanVetoRequired,
 81→  );
 82→
 83→  return {
 84→    passed: true,
 85→    policy_trace: policyTrace,
 86→    human_veto_required: humanVetoRequired,
 87→    warnings,
 88→    ...(evidenceRequirements ? { evidence_requirements: evidenceRequirements } : {}),
 89→  };
 90→};
 91→
 92→const extractEvidenceRequirementsFromPolicies = (
 93→  evaluatedPolicies: EvaluatedPolicy[],
 94→): PolicyEvidenceRequirements | undefined => {
 95→  const withRequirement = evaluatedPolicies.find(
 96→    (entry) => !entry.denied && entry.evidenceRequirement !== undefined,
 97→  );
 98→
 99→  if (!withRequirement?.evidenceRequirement) return undefined;
100→
101→  return {
102→    min_count: withRequirement.evidenceRequirement.min_count,
103→    ...(withRequirement.evidenceRequirement.required_types
104→      ? { required_types: withRequirement.evidenceRequirement.required_types }
105→      : {}),
106→  };
107→};
108→
109→// ---------------------------------------------------------------------------
110→// Composition Root (single effect boundary)
111→// ---------------------------------------------------------------------------
112→
113→export const evaluatePolicyGate = async (
114→  surreal: Surreal,
115→  identityId: RecordId<"identity">,
116→  workspaceId: RecordId<"workspace">,
117→  intentContext: IntentEvaluationContext,
118→): Promise<PolicyGateResult> => {
119→  // Effect boundary: single DB read
120→  const rawPolicies = await loadActivePolicies(surreal, identityId, workspaceId);
121→
122→  // Pure deduplication
123→  const deduplicated = deduplicatePolicies(rawPolicies);
124→
125→  // Engine cache: per-gate-call (avoids module-level mutable singleton per AGENTS.md)
126→  const engineCache = createEngineCache();
127→
128→  const evaluatedPolicies: EvaluatedPolicy[] = [];
129→  const allWarnings: PolicyGateWarning[] = [];
130→
131→  // Evaluate each policy via Rego; short-circuit on first deny
132→  for (const policy of deduplicated) {
133→    const policyId = policy.id.id as string;
134→
135→    let result: RegoEvaluationResult;
136→    try {
137→      result = await evaluateRegoPolicy(
138→        policy.rego_source,
139→        policyId,
140→        policy.version,
141→        intentContext,
142→        engineCache,
143→      );
144→    } catch (err: unknown) {
145→      // Fail-closed: WASM load failure or engine error → deny
146→      const message = err instanceof Error ? err.message : String(err);
147→      return {
148→        passed: false,
149→        reason: `Policy evaluation error: ${message}`,
150→        policy_trace: [],
151→        deny_rule_id: policyId,
152→        warnings: [{ rule_id: policyId, field: "rego_source", policy_id: policyId }],
153→      };
154→    }
155→
156→    const denied = result.decision === "deny";
157→    evaluatedPolicies.push({
158→      policyId,
159→      policyVersion: policy.version,
160→      humanVetoRequired: policy.human_veto_required,
161→      denied,
162→      denyMessages: result.messages,
163→      evidenceRequirement: result.evidence_requirement,
164→      warnings: [],
165→    });
166→
167→    if (denied) {
168→      return buildGateResult(evaluatedPolicies, true, allWarnings);
169→    }
170→  }
171→
172→  const evidenceRequirements = extractEvidenceRequirementsFromPolicies(evaluatedPolicies);
173→
174→  return buildGateResult(evaluatedPolicies, false, allWarnings, evidenceRequirements);
175→};
176→

